import React from 'react';
import Navbar from "../components/Navbar";
import EventsSlider from "../components/EventsSlider";
import CardContainer from '../components/CardContainer';
import MiniSlider from '../components/MiniSlider';
function Home() {
  return (
    <div>
      <Navbar />
      <EventsSlider />
      <MiniSlider/>
      <div className="home-section" style={{ backgroundColor: '#F5F9FF' }}>
        <h1 className="section-title">Başvurunu Bekleyen Etkinlikler</h1>
        <CardContainer />
      </div>
    </div>
  );
}

export default Home;
